/** A word that means one thing in one place and another elsewhere: [where, en, pt, es] — before PHRASES. */
export const CONTEXTUAL: ReadonlyArray<readonly [selector: string, en: string, pt: string, es: string]> = [
  ['.side-nav, .hdr-tabs, .hdr-h1, .mm-bar', 'Home', 'Início', 'Inicio'],
  // A stats column, not the net on a court.
  ['th', 'Net', 'Saldo', 'Neto'],
];

const MONTHS_SHORT: Readonly<Record<string, readonly [string, string]>> = {
  Jan: ['Jan', 'Ene'], Feb: ['Fev', 'Feb'], Mar: ['Mar', 'Mar'], Apr: ['Abr', 'Abr'], May: ['Mai', 'May'], Jun: ['Jun', 'Jun'],
  Jul: ['Jul', 'Jul'], Aug: ['Ago', 'Ago'], Sep: ['Set', 'Sep'], Sept: ['Set', 'Sep'], Oct: ['Out', 'Oct'], Nov: ['Nov', 'Nov'], Dec: ['Dez', 'Dic'],
};
const WEEKDAYS: Readonly<Record<string, readonly [string, string]>> = {
  Mon: ['Seg', 'Lun'], Tue: ['Ter', 'Mar'], Wed: ['Qua', 'Mié'], Thu: ['Qui', 'Jue'], Fri: ['Sex', 'Vie'], Sat: ['Sáb', 'Sáb'], Sun: ['Dom', 'Dom'],
};
const MONTHS: Readonly<Record<string, readonly [string, string]>> = Object.fromEntries(
  PHRASES.slice(PHRASES.findIndex((r) => r[0] === 'January'), PHRASES.findIndex((r) => r[0] === 'December') + 1).map((r) => [r[0], [r[1], r[2]] as const]),
);

const col = (lang: 'pt' | 'es'): 0 | 1 => (lang === 'pt' ? 0 : 1);

/** Text with numbers or names in it: a pattern, and how to say it — from its captured pieces. */
export const PATTERNS: ReadonlyArray<readonly [RegExp, (lang: 'pt' | 'es', parts: string[]) => string]> = [
  // "Sat 3 Oct", "Sat 3 Oct 2026"
  [/^(Mon|Tue|Wed|Thu|Fri|Sat|Sun) (\d{1,2}) (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sept|Sep|Oct|Nov|Dec)\b(.*)$/,
    (l, [w, d, m, rest]) => `${WEEKDAYS[w][col(l)]} ${d} ${MONTHS_SHORT[m][col(l)]}${rest}`],
  // "Mon, 11 January 2027" — the header's
  [/^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), (\d{1,2}) (January|February|March|April|May|June|July|August|September|October|November|December) (\d{4})$/,
    (l, [w, d, m, y]) => `${WEEKDAYS[w][col(l)]}, ${d} ${MONTHS[m][col(l)].toLowerCase()} ${y}`],
  // "3 Oct 2026"
  [/^(\d{1,2}) (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sept|Sep|Oct|Nov|Dec) (\d{4})$/,
    (l, [d, m, y]) => `${d} ${MONTHS_SHORT[m][col(l)]} ${y}`],
  // "December 2026"
  [/^(January|February|March|April|May|June|July|August|September|October|November|December) (\d{4})$/,
    (l, [m, y]) => `${MONTHS[m][col(l)]} ${y}`],
  // "1st", "22nd"
  [/^(\d+)(st|nd|rd|th)$/, (_l, [n]) => `${n}.º`],
  [/^· version (.+)$/, (l, [v]) => (l === 'pt' ? `· versão ${v}` : `· versión ${v}`)],
  [/^Pixels drawn for each pixel of the page — never more than the screen has \(this one: (\d+)%\)\.$/,
    (l, [n]) => (l === 'pt'
      ? `Píxeis desenhados por cada píxel da página — nunca mais do que o ecrã tem (este: ${n}%).`
      : `Píxeles dibujados por cada píxel de la página — nunca más de los que tiene la pantalla (esta: ${n}%).`)],
];
